/* ------------------------------------------------- profile context menu */

let menuEl = null;

function closeProfileMenu() {
  menuEl?.remove();
  menuEl = null;
}

/**
 * Right-click (or long-press on a phone) a person in the sidebar for their
 * options. A real menu: arrow keys, Escape, and a click anywhere else close it.
 */
function openProfileMenu(profile, x, y, opener) {
  closeProfileMenu();
  const item = (label, run, cls = '') => h('button', {
    class: `ctx-item ${cls}`, type: 'button', role: 'menuitem',
    onclick: () => { closeProfileMenu(); run(); },
  }, label);
  menuEl = h('div', { class: 'ctx-menu', role: 'menu', 'aria-label': `${profile.name} options` },
    h('div', { class: 'ctx-head', text: profile.name }),
    item('Open shelf', () => go(`#/p/${profile.id}`)),
    profile.id === state.me.id && THEMES_ON ? item('Decorate…', () => ctx.actions.openDecorate(profile)) : null,
    profile.id === state.me.id ? item('Account settings…', () => openSettings()) : null,
    profile.id !== state.me.id ? h('div', { class: 'ctx-sep', role: 'separator' }) : null,
    profile.id !== state.me.id ? item(`Remove ${profile.name} as a friend…`, async () => {
      if (!confirm(`Remove ${profile.name} from your friends?`)) return;
      try {
        await storage.api('/friends/remove', { method: 'POST', body: { id: profile.id } });
        if (state.route.profileId === profile.id) go(`#/p/${state.me.id}`);
        await ctx.actions.reloadFriends();
      } catch (err) { toast(friendlyError(err), true); }
    }, 'danger') : null);
  document.body.append(menuEl);
  // Keep it on screen near the pointer.
  const r = menuEl.getBoundingClientRect();
  menuEl.style.left = `${Math.max(8, Math.min(x, innerWidth - r.width - 8))}px`;
  menuEl.style.top = `${Math.max(8, Math.min(y, innerHeight - r.height - 8))}px`;
  const items = [...menuEl.querySelectorAll('.ctx-item')];
  items[0].focus();
  menuEl.addEventListener('keydown', (e) => {
    const i = items.indexOf(document.activeElement);
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length].focus();
    } else if (e.key === 'Escape' || e.key === 'Tab') {
      e.preventDefault();
      closeProfileMenu();
      opener?.focus();
    }
  });
}

document.addEventListener('pointerdown', (e) => { if (menuEl && !menuEl.contains(e.target)) closeProfileMenu(); });
window.addEventListener('resize', closeProfileMenu);
window.addEventListener('scroll', closeProfileMenu, true);

/**
 * Right-click and long-press on a sidebar person both open the menu.
 * `consumed()` tells the item's click handler that the tap which ended a long
 * press was already used, so it must not also navigate.
 */
function profileMenuHandlers(profile) {
  let timer = null;
  let longPressed = false;
  let start = null;
  const cancel = () => { clearTimeout(timer); timer = null; };
  return {
    consumed() { const was = longPressed; longPressed = false; return was; },
    handlers: {
      oncontextmenu: (e) => {
        e.preventDefault();
        if (longPressed) return; // Android fires this too after a long press.
        const r = e.currentTarget.getBoundingClientRect();
        // The keyboard's menu key fires this at 0,0 - anchor to the item instead.
        openProfileMenu(profile, e.clientX || r.left + 24, e.clientY || r.bottom, e.currentTarget);
      },
      // iPhones never fire contextmenu, so a held touch opens it there.
      onpointerdown: (e) => {
        if (e.pointerType !== 'touch') return;
        longPressed = false;
        start = { x: e.clientX, y: e.clientY };
        const target = e.currentTarget;
        timer = setTimeout(() => { longPressed = true; openProfileMenu(profile, start.x, start.y, target); }, 550);
      },
      // A finger always wobbles a little; only a real drag cancels.
      onpointermove: (e) => {
        if (timer && start && Math.hypot(e.clientX - start.x, e.clientY - start.y) > 10) cancel();
      },
      onpointerup: cancel,
      onpointercancel: cancel,
    },
  };
}
/* ------------------------------------------------------ pick my next read */

const PICK_FILTERS = [
  ['any', 'Anything', () => true],
  ['short', 'Short reads', (b) => b.pages && b.pages < 380],
  ['series', 'Next in a series', (b, lib) => b.series?.id
    && lib.books.some((x) => x.series?.id === b.series.id && (x.status === 'read' || x.status === 'reading'))],
  ['waiting', 'Waiting longest', () => true],
];

/**
 * The TBR jar: every book on the pile is a folded slip of paper in its spine
 * colour. The jar shakes, one slip rises out and unfolds into the book - for
 * when choosing is the hard part. "Waiting longest" gives older additions
 * more slips in the draw.
 */
ctx.actions.openPicker = (profile) => {
  const dialog = document.getElementById('picker-dialog');
  const body = clear(document.getElementById('picker-body'));
  const lib = state.libraries[profile.id] ?? { books: [] };
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const colourOf = shelfPalette(lib.books);
  let filter = 'any';
  const timers = [];
  const later = (ms, fn) => timers.push(setTimeout(fn, ms));
  const stop = () => { while (timers.length) clearTimeout(timers.pop()); };

  // The blurred cover behind the reveal is read from --art on the wrapper.
  const wrap = h('div', { class: 'picker-wrap jar-wrap' });
  const stage = h('div', { class: 'jar-stage' });
  const info = h('div', { class: 'picker-info', 'aria-live': 'polite' });
  const actions = h('div', { class: 'row end picker-actions' });

  const pool = () => {
    const test = PICK_FILTERS.find(([id]) => id === filter)[2];
    return lib.books.filter((b) => b.status === 'tbr' && test(b, lib));
  };

  function draw(books) {
    if (filter !== 'waiting') return books[Math.floor(Math.random() * books.length)];
    // Older additions get more tickets.
    const oldest = [...books].sort((a, b) => String(a.added).localeCompare(String(b.added)));
    const tickets = oldest.flatMap((b, i) => Array(oldest.length - i).fill(b));
    return tickets[Math.floor(Math.random() * tickets.length)];
  }

  /** The jar with a slip for each book (up to a jarful), settled at the bottom. */
  function jar(books) {
    const slips = [];
    // A small pile still fills the jar a little: two slips a book, up to a jarful.
    const n = Math.min(Math.max(books.length, Math.min(books.length * 2, 10)), 15);
    for (let i = 0; i < n; i++) {
      const b = books[i % books.length];
      const row = Math.floor(i / 5);
      slips.push(h('span', { class: 'slip', style: `--c:${colourOf(b).cloth};--x:${(i % 5) * 19 + (row % 2) * 9 + 8}px;--y:${row * 15}px;--r:${(i * 47) % 70 - 35}deg;--d:${(i * 13) % 9 * 40}ms` }));
    }
    return h('div', { class: 'jar' }, h('div', { class: 'jar-lid' }), h('div', { class: 'jar-glass' }, slips, h('span', { class: 'jar-shine' })));
  }

  function reveal(book) {
    wrap.setAttribute('style', cssArt(book.cover));
    wrap.classList.add('revealed');
    stage.append(h('div', { class: 'jar-reveal', style: `--c:${colourOf(book).cloth}` },
      h('div', { class: 'jar-paper' }, coverEl(book))));
    fill(info,
      h('div', { class: 'eyebrow', text: 'Your next read' }),
      h('div', { class: 'picker-title', text: book.title }),
      h('div', { class: 'book-meta', text: [authorNames(book), seriesLabel(book), book.pages ? `${book.pages} pages` : null].filter(Boolean).join(' · ') }),
      book.added ? h('div', { class: 'book-meta', text: `On the pile since ${fmtDate(book.added)}` }) : null);
    fill(actions,
      h('button', { class: 'btn secondary', type: 'button', onclick: () => shake() }, 'Shake again'),
      state.canWrite ? h('button', { class: 'btn', type: 'button', onclick: async (e) => {
        e.currentTarget.disabled = true;
        const ok = await saveLibrary(profile.id, (l) => {
          const t = l.books.find((b) => b.id === book.id);
          if (!t) throw new Error('That book is no longer on this shelf.');
          const previous = t.status;
          t.status = 'reading';
          applyStatusDates(t, previous);
          return l;
        }, `Start ${book.title}`);
        if (ok) { dialog.close(); toast(`Started ${book.title} — enjoy!`); }
      } }, 'Start reading') : null);
  }

  function shake() {
    stop();
    const books = pool();
    fill(actions);
    wrap.removeAttribute('style');
    wrap.classList.remove('revealed');
    if (!books.length) {
      fill(stage, art('books'));
      fill(info, h('p', { class: 'hint', text: 'Nothing on the pile matches that — try another filter.' }));
      return;
    }
    const winner = draw(books);
    fill(stage, jar(books));
    if (reduced) return reveal(winner);
    fill(info, h('p', { class: 'hint jar-hint', text: books.length === 1 ? 'Only one book in the jar…' : `${books.length} books in the jar…` }));
    const jarEl = stage.querySelector('.jar');
    // Shake, then a slip in the winner's colour rises out and unfolds.
    jarEl.classList.add('shaking');
    later(1100, () => {
      jarEl.classList.remove('shaking');
      stage.append(h('span', { class: 'slip flying', style: `--c:${colourOf(winner).cloth}` }));
    });
    later(1900, () => {
      stage.querySelector('.slip.flying')?.remove();
      jarEl.classList.add('settled');
      play('chime');
      reveal(winner);
    });
  }

  body.append(
    h('div', { class: 'seg picker-filters', role: 'tablist', 'aria-label': 'What kind of book' },
      PICK_FILTERS.map(([id, label]) => h('button', {
        class: 'seg-btn', type: 'button', role: 'tab', 'aria-selected': String(id === filter),
        onclick: (e) => {
          filter = id;
          for (const b of e.currentTarget.parentElement.children) b.setAttribute('aria-selected', String(b === e.currentTarget));
          shake();
        },
      }, label))),
    (wrap.append(h('div', { class: 'picker-wash', 'aria-hidden': 'true' }), stage), wrap),
    info,
    actions);
  dialog.addEventListener('close', stop, { once: true });
  dialog.showModal();
  shake();
};

