/**
 * Library data model, status rules, and watchlist derivation.
 *
 * Shared between the browser app and the Node watcher — keep it free of
 * anything platform-specific.
 */

// 'tbr' is a book you own and haven't read; 'wish' one you'd like to buy -
// drawn as a ghost spine among the to-read books until it's yours.
export const STATUSES = ['tbr', 'reading', 'read', 'abandoned', 'wish'];

/** Books on the to-read side of the shelf: owned and waiting, or wished for. */
export const onPile = (b) => b?.status === 'tbr' || b?.status === 'wish';

/**
 * Why a book was put down. "Might come back later" is a pause, not a verdict:
 * it does not count against the series the way giving up does.
 */
export const DNF_REASONS = [
  ['slow', 'Too slow'], ['not-for-me', 'Not for me'], ['style', 'Writing style'], ['characters', 'Didn’t connect with the characters'],
  ['content', 'Content I didn’t want'], ['lost-interest', 'Lost interest'], ['later', 'Might come back later'],
];
/** A clean did-not-finish record, or null. */
export function cleanDnf(raw) {
  if (!raw) return null;
  const ids = DNF_REASONS.map(([id]) => id);
  const reasons = [...new Set((raw.reasons ?? []).filter((r) => ids.includes(r)))];
  const note = String(raw.note ?? '').trim().slice(0, 500);
  const page = Number(raw.page) > 0 ? Math.round(Number(raw.page)) : null;
  return reasons.length || note || page ? { reasons, note, page } : null;
}
/** Paused rather than given up on: kept out of the dislike rules. */
export const pausedBook = (book) => book.status === 'abandoned' && (book.dnf?.reasons ?? []).includes('later');

/** Times a finished book has been read: once, plus its re-reads. */
export const timesRead = (book) => 1 + Math.max(0, Math.round(Number(book.rereads) || 0));

/** Ratings at or below this drop the series off the watchlist. */
export const DISLIKE_AT_OR_BELOW = 2;
/** Ratings at or above this start watching the author, not just the series. */
export const AUTHOR_WATCH_AT_OR_ABOVE = 4;

/**
 * Ratings go in half stars. Anything else - a CLI typo, an old record - is
 * snapped to the nearest half and clamped, so every rating on disk is one of
 * 0.5, 1, 1.5 ... 5 and the display never has to cope with 3.27.
 */
export function normaliseRating(value) {
  if (value == null || value === '') return null;
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return null;
  return Math.min(5, Math.max(0.5, Math.round(n * 2) / 2));
}

/* --------------------------------------------------------------- text --- */

// Zero-width and formatting characters that carry no meaning in a title but
// survive round-trips and break string comparison. Hardcover's records contain
// them - "A Court of Silver Flames" has a zero-width space after the "A".
const INVISIBLE = /[\u200B-\u200F\u2028\u2029\u2060\uFEFF\u00AD]/g;
// C0 and C1 control characters, never legitimate in a title.
const CONTROL = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g;

/**
 * Undo Latin-1/UTF-8 double-encoding ("mojibake").
 *
 * Text that has been through a byte-as-character round trip comes back as
 * a run of accented capitals. Re-reading those characters as bytes and
 * decoding them as UTF-8 reverses one layer; repeat until it settles.
 * Decoding strictly (fatal) means only a genuinely valid UTF-8 reading is
 * accepted, so legitimately accented text is left alone.
 */
export function repairMojibake(text) {
  let current = String(text ?? '');
  for (let pass = 0; pass < 4; pass++) {
    // Only characters that could have come from a single byte can be re-read.
    if (!/[\u00C2-\u00C3\u00E2]/.test(current)) break;
    let bytes;
    try {
      bytes = Uint8Array.from(current, (ch) => {
        const code = ch.charCodeAt(0);
        if (code > 0xff) throw new Error('not byte-sized');
        return code;
      });
    } catch {
      break;
    }
    let decoded;
    try {
      decoded = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
    } catch {
      break; // not double-encoded after all
    }
    if (decoded === current) break;
    current = decoded;
  }
  return current;
}

/**
 * Normalise text coming from an external source: repair double-encoding, drop
 * invisible and control characters, put accents into one canonical form so two
 * spellings of a title compare equal, and collapse stray whitespace.
 */
export function cleanText(text) {
  if (text == null) return text === undefined ? undefined : null;
  return repairMojibake(String(text))
    .normalize('NFC')
    .replace(INVISIBLE, '')
    .replace(CONTROL, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/* ------------------------------------------------------- searching a shelf */

/**
 * Match a book against a typed query.
 *
 * Every word must match something - title, author or series - so "maas court"
 * narrows rather than widening, which is what people expect from a search box
 * even though it is technically an AND of ORs.
 */
export function matchesQuery(book, query) {
  const needles = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!needles.length) return true;
  const hay = [
    book.title,
    ...(book.authors ?? []).map((a) => a.name),
    book.series?.name,
  ].filter(Boolean).join(' ').toLowerCase();
  return needles.every((n) => hay.includes(n));
}

export const RATING_FILTERS = [
  ['all', 'All'],
  ['4plus', '4★ and up'],
  ['unrated', 'Unrated'],
];

export function matchesRating(book, filter) {
  if (filter === '4plus') return typeof book.rating === 'number' && book.rating >= 4;
  if (filter === 'unrated') return !book.rating;
  return true;
}

/* --------------------------------------------------------------- tags --- */

/**
 * Hardcover's genre and mood lists are crowd-sourced, so they are a mix of
 * real genres, reading-shelf names ("did-not-finish"), formats ("audiobook")
 * and occasionally several genres joined with semicolons. Filter the noise out
 * rather than charting it.
 */
const TAG_NOISE = new Set([
  // shelf names people use as tags
  'did-not-finish', 'dnf', 'to-read', 'currently-reading', 'read', 'owned', 'own',
  'favorites', 'favourites', 'wishlist', 'wish-list', 'abandoned', 're-read', 'reread',
  'tbr', 'series', 'default', 'all', 'books', 'book',
  // formats
  'audiobook', 'audible', 'ebook', 'e-book', 'kindle', 'paperback', 'hardcover',
  'hardback', 'library', 'physical',
  // too broad to say anything
  'fiction', 'non-fiction', 'nonfiction', 'novel', 'novels', 'general', 'literature',
  'adult', 'books-i-own',
]);

/** Split, trim, de-duplicate and drop the noise. Order is preserved. */
export function cleanTags(list, limit = 6) {
  const out = [];
  const seen = new Set();
  for (const raw of list ?? []) {
    // A single entry is sometimes "Epic; Action & Adventure; Historical".
    for (const part of String(raw).split(/[;,]/)) {
      const value = cleanText(part);
      if (!value || value.length > 40) continue;
      const key = value.toLowerCase();
      if (TAG_NOISE.has(key) || seen.has(key)) continue;
      seen.add(key);
      out.push(value);
      if (out.length >= limit) return out;
    }
  }
  return out;
}

/** Count tag frequency across books, most common first. */
export function tagCounts(books, field = 'genres') {
  const counts = new Map();
  for (const book of books) {
    for (const tag of book[field] ?? []) {
      counts.set(tag, (counts.get(tag) ?? 0) + 1);
    }
  }
  return [...counts.entries()]
    .map(([tag, count]) => ({ tag, count }))
    .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag));
}

/** ISO date (YYYY-MM-DD) for "today", in local time rather than UTC. */
export function today(now = new Date()) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
}

/**
 * Build a library record from a Hardcover search hit or book detail.
 *
 * Everything derived from Hardcover is filled in here; the only fields the
 * human ever supplies are `status`, `rating` and `note`. `started`/`finished`
 * are deliberately null — we never prompt for dates, they are opt-in extras
 * the user can fill later from the book's detail panel.
 */
export function bookFromHardcover(hit, { status = 'tbr', rating = null, note = '' } = {}) {
  if (!STATUSES.includes(status)) throw new Error(`Unknown status: ${status}`);

  // Everything from Hardcover goes through cleanText: their records contain
  // zero-width characters and occasional mis-encoded text, and left alone those
  // corrupt further on every save.
  const authors = (hit.authors ?? [])
    .map((a) => (typeof a === 'string' ? { id: null, name: a } : a))
    .map((a) => ({ ...a, name: cleanText(a.name) }));

  const book = {
    id: `hc:${hit.id}`,
    hardcoverId: String(hit.id),
    title: cleanText(hit.title),
    authors,
    series: hit.series ? { ...hit.series, name: cleanText(hit.series.name) } : null,
    pages: hit.pages ?? null,
    released: hit.releaseDate ?? null,
    releaseYear: hit.releaseYear ?? null,
    cover: hit.image ?? null,
    slug: hit.slug ?? null,
    genres: cleanTags(hit.genres, 6),
    moods: cleanTags(hit.moods, 5),

    status,
    rating,
    note,

    added: today(),
    // When it was read, at whatever precision the reader actually remembers:
    // "2026", "2026-03", or "2026-03-14". See readOn helpers below.
    readOn: null,
    started: null,
    finished: null,
  };

  // Adding a book straight onto "reading" or "finished" is a status change
  // like any other, so it gets the same dates.
  return applyStatusDates(book, null);
}

/**
 * A copy of a book from someone else's shelf for your own: what Hardcover
 * says about it, none of what they did with it (rating, note, dates, gifts).
 */
export function bookFromShelf(book, { status = 'wish' } = {}) {
  if (!STATUSES.includes(status)) throw new Error(`Unknown status: ${status}`);
  const keep = ['id', 'hardcoverId', 'title', 'authors', 'series', 'pages', 'released', 'releaseYear', 'cover', 'slug', 'genres', 'moods'];
  const copy = Object.fromEntries(keep.map((k) => [k, structuredClone(book[k] ?? null)]));
  return applyStatusDates({ ...copy, genres: copy.genres ?? [], moods: copy.moods ?? [], authors: copy.authors ?? [],
    status, rating: null, note: '', added: today(), readOn: null, started: null, finished: null }, null);
}

export function emptyLibrary() {
  return { books: [], watch: { series: {}, authors: {} } };
}

export function findBook(library, id) {
  return library.books.find((b) => b.id === id) ?? null;
}

/**
 * Fuzzy lookup by title, for the CLI where the user types a partial name.
 * Returns every match so the caller can disambiguate rather than guess.
 */
export function matchBooks(library, query) {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const exact = library.books.filter((b) => b.title.toLowerCase() === q);
  if (exact.length) return exact;
  return library.books.filter((b) => b.title.toLowerCase().includes(q));
}

/**
 * Apply a status change, keeping the optional dates coherent without ever
 * demanding them: we only stamp a date if one is volunteered.
 */
export function setStatus(book, status, { rating, note, now } = {}) {
  if (!STATUSES.includes(status)) throw new Error(`Unknown status: ${status}`);
  const previous = book.status;
  book.status = status;
  if (rating !== undefined) book.rating = rating;
  if (note !== undefined) book.note = note;
  applyStatusDates(book, previous, now);
  return book;
}

/**
 * Record the dates a status change implies.
 *
 * Moving a book to "reading now" stamps the day you started it, and that date
 * survives into the finished record, so a book you actually tracked ends up
 * with both ends of the read without anyone typing a date.
 *
 * Nothing already recorded is ever overwritten: an explicit date the reader
 * set by hand outranks anything inferred, and re-opening a book you had
 * already started keeps the original start date rather than resetting it.
 *
 * A book marked read without ever passing through "reading" gets a finish date
 * only - we genuinely do not know when it was started, and guessing would be
 * worse than leaving it blank.
 */
export function applyStatusDates(book, previousStatus, now = today()) {
  if (book.status === previousStatus) return book;

  if (book.status === 'reading' && !book.started) {
    book.started = now;
  }

  if (book.status === 'read') {
    if (!book.finished) book.finished = now;
    // Keep the simplified read date in step, unless a coarser one was chosen
    // deliberately - "2019" must not be clobbered by today's date.
    if (!isValidReadOn(book.readOn)) book.readOn = book.finished;
  }

  return book;
}

/* ------------------------------------------------------- watchlist rules */

/**
 * Derive the watchlist from the library, then re-apply manual overrides.
 *
 * This is recomputed from scratch on every change rather than mutated
 * incrementally, so the rules can never drift out of sync with the shelf.
 *
 * Rules:
 *   - reading or finishing a book  → watch its series
 *   - rating <= 2, or abandoning   → drop that series
 *   - rating >= 4                  → also watch the author
 *   - explicit watch/unwatch always wins
 */
export function deriveWatchlist(library) {
  const series = new Map();
  const authors = new Map();

  // Two passes, because a single pass is order-dependent: whether a dislike
  // suppressed a series would depend on whether the disliked book happened to
  // sit before or after the liked one in the array. Collect the vetoes first,
  // then add only what survives them.
  const vetoed = new Set();
  for (const book of library.books) {
    if (!book.series?.id) continue;
    const disliked =
      (book.status === 'abandoned' && !pausedBook(book)) ||
      (typeof book.rating === 'number' && book.rating <= DISLIKE_AT_OR_BELOW);
    if (disliked) vetoed.add(book.series.id);
  }

  for (const book of library.books) {
    if (book.series?.id && !vetoed.has(book.series.id)) {
      const engaged = book.status === 'reading' || book.status === 'read';
      if (engaged && !series.has(book.series.id)) {
        series.set(book.series.id, { id: book.series.id, name: book.series.name, reason: 'auto' });
      }
    }

    // Author watching is deliberately not vetoed the same way. Giving up on one
    // book by someone whose other work you rated 5 says nothing about whether
    // you want to hear about their next one.
    const loved = typeof book.rating === 'number' && book.rating >= AUTHOR_WATCH_AT_OR_ABOVE;
    if (loved) {
      for (const a of book.authors ?? []) {
        if (a.id && !authors.has(a.id)) {
          authors.set(a.id, { id: a.id, name: a.name, reason: 'auto' });
        }
      }
    }
  }

  const overrides = library.watch ?? { series: {}, authors: {} };
  applyOverrides(series, overrides.series);
  applyOverrides(authors, overrides.authors);

  return {
    series: Object.fromEntries(series),
    authors: Object.fromEntries(authors),
  };
}

function applyOverrides(map, overrides = {}) {
  for (const [id, override] of Object.entries(overrides)) {
    if (override.watching === false) map.delete(id);
    else if (override.watching === true) {
      map.set(id, { id, name: override.name ?? map.get(id)?.name ?? id, reason: 'manual' });
    }
  }
}

/** Record an explicit watch/unwatch that survives recomputation. */
export function setWatchOverride(library, kind, id, name, watching) {
  library.watch ??= { series: {}, authors: {} };
  library.watch[kind] ??= {};
  library.watch[kind][id] = { watching, name };
  return library;
}

/* ------------------------------------------------------------------ misc */

/**
 * Everyone whose books you are reading or have read, plus anyone on the
 * author watchlist.
 *
 * Broader than the watchlist on purpose. The watchlist decides what is worth
 * interrupting you for (authors you rated 4+); this decides what is worth
 * *showing* - the Upcoming page's "from authors you read" column, where a
 * forthcoming book by someone you rated 3 is still interesting to see.
 * An explicit unwatch removes an author from both.
 */
export function readAuthors(library) {
  const out = new Map();
  for (const book of library.books ?? []) {
    if (book.status !== 'read' && book.status !== 'reading') continue;
    for (const a of book.authors ?? []) {
      if (a.id && !out.has(a.id)) out.set(a.id, { id: a.id, name: a.name });
    }
  }
  for (const [id, a] of Object.entries(deriveWatchlist(library).authors)) {
    if (!out.has(id)) out.set(id, { id, name: a.name });
  }
  for (const [id, o] of Object.entries(library.watch?.authors ?? {})) {
    if (o.watching === false) out.delete(id);
  }
  return Object.fromEntries(out);
}

/** Hardcover ids of every book on a shelf, whatever its status. */
export function onShelfIds(library) {
  return new Set((library.books ?? []).map((b) => String(b.hardcoverId ?? String(b.id).replace(/^hc:/, ''))));
}

/* ------------------------------------------------ hidden and tracked books */

/**
 * Books someone has said they do not care about. One list serves every place
 * that suggests a book - Upcoming, "next in series", author releases - because
 * "not interested" means the same thing wherever you said it.
 */
export function hiddenIds(library) {
  return new Set(Object.keys(library.hidden ?? {}));
}

export function hideBook(library, bookId, title, now = today()) {
  library.hidden ??= {};
  library.hidden[String(bookId)] = { title, at: now };
  return library;
}

export function unhideBook(library, bookId) {
  if (library.hidden) delete library.hidden[String(bookId)];
  return library;
}

/** Follow one specific book's release, whoever wrote it. */
export function trackBook(library, hit, now = today()) {
  library.tracked ??= [];
  const bookId = String(hit.id ?? hit.bookId);
  if (library.tracked.some((t) => String(t.bookId) === bookId)) return library;
  library.tracked.push({
    bookId,
    title: cleanText(hit.title),
    authors: (hit.authors ?? []).map((a) => (typeof a === 'string' ? { id: null, name: a } : a)),
    series: hit.series ? { id: hit.series.id, name: cleanText(hit.series.name), position: hit.series.position ?? null } : null,
    releaseDate: hit.releaseDate ?? null,
    releaseYear: hit.releaseYear ?? null,
    image: hit.image ?? null,
    slug: hit.slug ?? null,
    added: now,
  });
  unhideBook(library, bookId);
  return library;
}

export function untrackBook(library, bookId) {
  library.tracked = (library.tracked ?? []).filter((t) => String(t.bookId) !== String(bookId));
  return library;
}

/* --------------------------------------------------------- recommendations */

/**
 * A recommendation lives in the *recipient's* library, so it arrives with
 * their shelf and needs no file of its own. It carries a complete book record,
 * so accepting it is one click with no second trip to Hardcover.
 */
export function addRecommendation(library, { book, from, note = '', now = today() }) {
  library.recommendations ??= [];
  const bookId = String(book.hardcoverId ?? book.id).replace(/^hc:/, '');
  const open = library.recommendations.find((r) => r.bookId === bookId && r.from === from && r.status === 'new');
  if (open) throw new Error('You have already recommended that one.');
  if (onShelfIds(library).has(bookId)) throw new Error('That book is already on their shelf.');
  const record = {
    ...book,
    status: 'tbr', rating: null, note: '',
    readOn: null, started: null, finished: null,
  };
  library.recommendations.push({
    id: `${from}:${bookId}:${now}`,
    bookId,
    from,
    note: cleanText(note) ?? '',
    at: now,
    status: 'new',
    book: record,
  });
  return library;
}

/** Accept (onto the to-read pile) or dismiss a recommendation. */
export function answerRecommendation(library, recId, answer, now = today()) {
  const rec = (library.recommendations ?? []).find((r) => r.id === recId);
  if (!rec) throw new Error('That recommendation is no longer there.');
  rec.status = answer;
  rec.answeredAt = now;
  if (answer === 'added' && !onShelfIds(library).has(rec.bookId)) {
    library.books.push({ ...rec.book, status: 'tbr', added: now, recommendedBy: rec.from });
  }
  return library;
}

/* ------------------------------------------------------------------ goals */

export function setGoal(library, year, target) {
  library.goals ??= {};
  const n = Math.round(Number(target));
  if (!Number.isFinite(n) || n <= 0) delete library.goals[String(year)];
  else library.goals[String(year)] = n;
  return library;
}

/**
 * How a yearly goal is going. "Expected" is where a steady pace would have
 * you by today, so being two books ahead in March says something real.
 */
export function goalProgress(library, year, now = today()) {
  const target = library.goals?.[String(year)] ?? null;
  const done = (library.books ?? []).filter((b) => b.status === 'read' && readYearOf(b) === Number(year)).length;
  if (!target) return { target: null, done };

  const thisYear = Number(now.slice(0, 4));
  let fraction;
  if (Number(year) < thisYear) fraction = 1;
  else if (Number(year) > thisYear) fraction = 0;
  else {
    const start = Date.parse(`${year}-01-01T00:00:00Z`);
    const end = Date.parse(`${Number(year) + 1}-01-01T00:00:00Z`);
    fraction = (Date.parse(`${now}T00:00:00Z`) - start) / (end - start);
  }
  const expected = target * fraction;
  return {
    target, done,
    expected,
    ahead: Math.round(done - expected),
    percent: Math.min(100, (done / target) * 100),
    met: done >= target,
    finished: fraction >= 1,
  };
}

/** Union of every profile's watchlist, so each series is fetched only once. */
export function unionWatchlists(profiles) {
  const series = new Map();
  const authors = new Map();
  const readers = new Map();
  const tracked = new Map();
  for (const [profileId, library] of Object.entries(profiles)) {
    for (const [id, a] of Object.entries(readAuthors(library))) {
      if (!readers.has(id)) readers.set(id, { ...a, watchers: [] });
      readers.get(id).watchers.push(profileId);
    }
    for (const t of library.tracked ?? []) {
      const id = String(t.bookId);
      if (!tracked.has(id)) tracked.set(id, { id, title: t.title, watchers: [] });
      tracked.get(id).watchers.push(profileId);
    }
    const w = deriveWatchlist(library);
    for (const [id, s] of Object.entries(w.series)) {
      if (!series.has(id)) series.set(id, { ...s, watchers: [] });
      series.get(id).watchers.push(profileId);
    }
    for (const [id, a] of Object.entries(w.authors)) {
      if (!authors.has(id)) authors.set(id, { ...a, watchers: [] });
      authors.get(id).watchers.push(profileId);
    }
  }
  return {
    series: [...series.values()],
    authors: [...authors.values()],
    // Fetched for display; only `authors` above produce news.
    readAuthors: [...readers.values()],
    tracked: [...tracked.values()],
  };
}

/* ------------------------------------------------------------ read dates */

/**
 * When a book was read, at whatever precision is known.
 *
 * Stored as a partial ISO date: "2026", "2026-03" or "2026-03-14". Partial
 * ISO dates sort correctly as plain strings and never imply a precision the
 * reader did not actually claim — which matters, because most books were read
 * long before anyone thought to log them.
 */
export const READ_PRECISION = ['year', 'month', 'day'];

export function precisionOf(readOn) {
  if (!readOn) return null;
  const parts = String(readOn).split('-');
  return parts.length === 1 ? 'year' : parts.length === 2 ? 'month' : 'day';
}

export function isValidReadOn(readOn) {
  return typeof readOn === 'string' && /^\d{4}(-\d{2}(-\d{2})?)?$/.test(readOn);
}

/**
 * The best available answer for when a book was read. Falls back to the exact
 * finish date, so books logged before this field existed still group correctly.
 */
export function readOnOf(book) {
  if (isValidReadOn(book.readOn)) return book.readOn;
  if (book.finished) return String(book.finished).slice(0, 10);
  return null;
}

export function readYearOf(book) {
  const value = readOnOf(book);
  return value ? Number(value.slice(0, 4)) : null;
}

/** Narrow a readOn to a given precision, e.g. "2026-03-14" -> "2026-03". */
export function coarsen(readOn, precision) {
  if (!readOn) return null;
  const length = precision === 'year' ? 4 : precision === 'month' ? 7 : 10;
  return String(readOn).slice(0, length);
}

/**
 * What is wrong with a pair of exact reading dates, or null if nothing is.
 * Both are optional; together they must be in order, and neither can be in
 * the future - a finish date next month is always a slip of the picker.
 */
export function datesProblem({ started, finished }, now = today()) {
  if (started && started > now) return 'The start date is in the future.';
  if (finished && finished > now) return 'The finish date is in the future.';
  if (started && finished && finished < started) return 'The finish date is before the start date.';
  return null;
}

/* ------------------------------------------------------------- undoing */

/**
 * Take back a "No thanks". Only a pass can be reopened: an accepted
 * recommendation already put a book on the shelf, and that is undone by
 * removing the book.
 */
export function reopenRecommendation(library, recId) {
  const rec = (library.recommendations ?? []).find((r) => r.id === recId);
  if (!rec) throw new Error('That recommendation is no longer there.');
  if (rec.status === 'dismissed') {
    rec.status = 'new';
    delete rec.answeredAt;
  }
  return library;
}

/**
 * Put back a book that was just removed, exactly as it was. If it has been
 * re-added in the meantime the shelf copy wins - restoring over it would
 * throw away whatever happened since.
 */
export function restoreBook(library, book) {
  if (!library.books.some((b) => b.id === book.id)) library.books.push(structuredClone(book));
  return library;
}

/* --------------------------------------------------------------- profiles */

/** Colours offered for a new person, chosen to read on light and dark. */
export const PROFILE_COLOURS = [
  '#6366f1', '#ec4899', '#0ea5e9', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#14b8a6', '#84cc16', '#f97316',
];

/** Everyone who has not been removed. */
export function activeProfiles(doc) {
  return (doc?.profiles ?? []).filter((p) => !p.removed);
}

/**
 * The id a name becomes: lowercase letters, digits and dashes, which is what
 * the Worker accepts in a file path. Accented letters lose their accents;
 * a name with nothing usable left ("李") becomes "reader".
 */
export function profileId(name, taken = []) {
  const base = String(name ?? '').normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 30) || 'reader';
  const used = new Set(taken);
  if (!used.has(base)) return base;
  for (let n = 2; ; n++) if (!used.has(`${base}-${n}`)) return `${base}-${n}`;
}

/**
 * Add a person. Ids are never reused - not even a removed person's - so a new
 * "Sam" can never inherit an old Sam's shelf.
 */
export function addProfile(doc, { name, colour, theme }, now = new Date().toISOString()) {
  doc.profiles ??= [];
  const clean = cleanText(name ?? '');
  if (!clean) throw new Error('Give the new profile a name.');
  if (clean.length > 30) throw new Error('Keep the name to 30 characters or fewer.');
  const clash = activeProfiles(doc).find((p) => p.name.toLowerCase() === clean.toLowerCase());
  if (clash) throw new Error(`There is already someone called ${clash.name}.`);
  const profile = {
    id: profileId(clean, doc.profiles.map((p) => p.id)),
    name: clean,
    colour: /^#[0-9a-f]{6}$/i.test(colour ?? '') ? colour : PROFILE_COLOURS[doc.profiles.length % PROFILE_COLOURS.length],
    lastSeen: null,
    created: now,
    theme: PROFILE_THEMES.some((t) => t.id === theme) ? theme : 'classic',
  };
  doc.profiles.push(profile);
  return profile;
}

/**
 * Remove a person from the site. Their entry stays, marked removed, and their
 * shelf file is left untouched - so a removal is undone by restoring, and the
 * nightly check simply stops looking for them.
 */
export function removeProfile(doc, id, now = new Date().toISOString()) {
  const p = (doc.profiles ?? []).find((x) => x.id === id && !x.removed);
  if (!p) throw new Error('That profile is not here any more.');
  if (activeProfiles(doc).length <= 1) throw new Error('The last profile cannot be removed.');
  p.removed = now;
  return p;
}

export function restoreProfile(doc, id) {
  const p = (doc.profiles ?? []).find((x) => x.id === id && x.removed);
  if (!p) throw new Error('That profile is not in the removed list.');
  if (activeProfiles(doc).some((x) => x.name.toLowerCase() === p.name.toLowerCase())) {
    throw new Error(`Someone called ${p.name} is already here — rename them first.`);
  }
  delete p.removed;
  return p;
}

/* -------------------------------------------------------- reading progress */

const MS_DAY = 86_400_000;
const dayNumber = (iso) => Math.floor(Date.parse(`${String(iso).slice(0, 10)}T00:00:00Z`) / MS_DAY);

/**
 * Record how far into a book someone is. Optional, like every date here:
 * a book with no progress is simply "reading". Pages are clamped to the book.
 */
export function setProgress(book, page, now = today()) {
  const n = Math.max(0, Math.round(Number(page)));
  if (!Number.isFinite(n)) throw new Error('Progress needs a page number.');
  const capped = book.pages ? Math.min(n, book.pages) : n;
  book.progress = { page: capped, updated: now };
  return book;
}

/**
 * How a current read is going: percent, pace since starting, and when it
 * will be finished at that pace. The pace is only claimed once there is a
 * start date and some pages behind it - "you'll finish in 400 days" on day
 * one would be noise.
 */
export function readingEstimate(book, now = today()) {
  const total = book.pages ?? null;
  const page = book.progress?.page ?? null;
  const percent = total && page != null ? Math.min(100, Math.round((page / total) * 100)) : null;
  const out = { page, total, percent, pagesPerDay: null, daysLeft: null, finishOn: null, day: null };
  if (book.started) out.day = Math.max(1, dayNumber(now) - dayNumber(book.started) + 1);
  if (!book.started || !page || !total) return out;
  const pace = page / out.day;
  if (pace <= 0) return out;
  out.pagesPerDay = Math.round(pace * 10) / 10;
  out.daysLeft = Math.ceil((total - page) / pace);
  out.finishOn = new Date((dayNumber(now) + out.daysLeft) * MS_DAY).toISOString().slice(0, 10);
  return out;
}

/* -------------------------------------------------------------- reactions */

export const REACTIONS = ['🔥', '😍', '😂', '😮', '😢', '👏'];

/**
 * React to someone's rating of a book, or to their finishing it. Reactions
 * live in the library of the person reacted to, beside the book.
 *
 * Anonymous for now: `by` is stored as null. When accounts arrive it holds
 * the reactor's profile id, and nothing else here needs to change - the
 * summaries already count entries rather than assuming who made them.
 */
export function addReaction(library, bookId, on, emoji, { by = null, now = new Date().toISOString() } = {}) {
  if (!REACTIONS.includes(emoji)) throw new Error('Unknown reaction.');
  if (on !== 'rating' && on !== 'finished') throw new Error('React to a rating or a finish.');
  library.reactions ??= {};
  library.reactions[bookId] ??= [];
  library.reactions[bookId].push({ emoji, on, by, at: now });
  return library;
}

/** Counts per emoji for one book's rating or finish, most first. */
export function reactionSummary(library, bookId, on) {
  const counts = new Map();
  for (const r of library.reactions?.[bookId] ?? []) {
    if (r.on === on) counts.set(r.emoji, (counts.get(r.emoji) ?? 0) + 1);
  }
  return [...counts.entries()].map(([emoji, count]) => ({ emoji, count })).sort((a, b) => b.count - a.count);
}

/* ------------------------------------------------------------- audiobooks */

/** Mark a book as listened to, with what Hardcover knows of the recording. */
export function setAudiobook(book, audio) {
  if (audio === false) {
    delete book.format;
    delete book.audio;
    return book;
  }
  book.format = 'audiobook';
  const narrators = (audio?.narrators ?? []).map((n) => cleanText(n)).filter(Boolean).slice(0, 6);
  if (audio?.seconds > 0 || narrators.length) book.audio = { seconds: audio?.seconds > 0 ? Math.round(audio.seconds) : null, narrators };
  else delete book.audio;
  return book;
}

export const isAudiobook = (book) => book.format === 'audiobook';

/** Hours of listening an audiobook takes, to a tenth. */
export const audioHours = (book) => (isAudiobook(book) && book.audio?.seconds ? Math.round(book.audio.seconds / 360) / 10 : 0);

/* -------------------------------------------------------- who's who notes */

/**
 * Notes on a series' people, kept spoiler-safe: each entry records the book
 * it comes from, and is only shown to someone reading at or past that book.
 */
export function upsertSeriesPerson(library, seriesId, { id, name, note = '', from = 1 }, now = today()) {
  const clean = cleanText(name ?? '');
  if (!clean) throw new Error('Give the character a name.');
  library.seriesNotes ??= {};
  const s = (library.seriesNotes[seriesId] ??= { people: [] });
  const entry = { id: id ?? `p${Date.now().toString(36)}${Math.random().toString(36).slice(2, 5)}`,
    name: clean, note: cleanText(note) ?? '', from: Number(from) || 1, updated: now };
  const i = s.people.findIndex((p) => p.id === entry.id);
  if (i >= 0) s.people[i] = entry; else s.people.push(entry);
  return entry;
}

export function removeSeriesPerson(library, seriesId, personId) {
  const s = library.seriesNotes?.[seriesId];
  if (s) s.people = s.people.filter((p) => p.id !== personId);
  return library;
}

/** Who's who as far as a reader has got: what is safe, and how many wait further on. */
export function whosWho(library, seriesId, upTo = Infinity) {
  const people = [...(library.seriesNotes?.[seriesId]?.people ?? [])]
    .sort((a, b) => a.from - b.from || a.name.localeCompare(b.name));
  return { shown: people.filter((p) => p.from <= upTo), hidden: people.filter((p) => p.from > upTo).length };
}

/* ----------------------------------------------------------- profile looks */

/**
 * The colour palettes a person can choose for their pages. Two colours each:
 * the accent that buttons and links take, and a second that partners it in
 * gradients and glows. Classic is the site's own terracotta, untouched.
 */
export const PROFILE_THEMES = [
  { id: 'classic', name: 'Classic', accent: null, accent2: null, wallpaper: 'plain' },
  { id: 'forest', name: 'Forest & olive', accent: '#2f6b4f', accent2: '#8a9a3a', wallpaper: 'leaves' },
  { id: 'ocean', name: 'Ocean & teal', accent: '#1f6f8b', accent2: '#2a9d8f', wallpaper: 'waves' },
  { id: 'rose', name: 'Rose & apricot', accent: '#b0476a', accent2: '#d98a6a', wallpaper: 'florals' },
  { id: 'midnight', name: 'Midnight & violet', accent: '#4b5bb8', accent2: '#8a5cc8', wallpaper: 'stars' },
  { id: 'sunset', name: 'Sunset & gold', accent: '#c2622d', accent2: '#d9a12f', wallpaper: 'stripes' },
  { id: 'ink', name: 'Monochrome ink', accent: '#2e2e33', accent2: '#7a7a82', wallpaper: 'plain' },
  { id: 'lavender', name: 'Lavender & sage', accent: '#7a62a8', accent2: '#7f9a72', wallpaper: 'florals' },
];

/** Heading typefaces, chosen separately from the colours. Body text never changes. */
export const PROFILE_FONTS = [
  { id: 'classic', name: 'Classic serif', family: 'Newsreader' },
  { id: 'elegant', name: 'Elegant', family: 'Playfair Display' },
  { id: 'storybook', name: 'Storybook', family: 'Fraunces' },
  { id: 'modern', name: 'Modern', family: 'Outfit' },
];

export const ROOMS = ['library', 'fire', 'rain', 'cafe'];

/**
 * What can be changed inside the room. 'room' everywhere means "what this
 * room has by default", so changing room keeps it looking right.
 */
export const ROOM_OPTIONS = {
  wall: ['room', 'cream', 'sage', 'dusk-blue', 'plum', 'charcoal'],
  wood: ['room', 'walnut', 'oak', 'cherry', 'ebony', 'driftwood'],
  rug: ['room', 'crimson', 'navy', 'sage', 'gold', 'none'],
  lamp: ['room', 'library', 'fire', 'rain', 'cafe'],
  pet: ['none', 'cat', 'dog'],
};

const DEFAULT_LOOK = { palette: 'classic', font: 'classic', room: 'library', wall: 'room', wood: 'room', rug: 'room', lamp: 'room', pet: 'none', seasons: false, stamp: true };

/**
 * A person's whole look, with anything missing or unknown at its default -
 * including profiles saved before looks existed, whose `theme` becomes the
 * palette.
 */
export function lookOf(profile) {
  const raw = { ...(profile?.theme ? { palette: profile.theme } : {}), ...(profile?.look ?? {}) };
  return cleanLook(raw);
}

function cleanLook(raw) {
  const pick = (value, allowed, fallback) => (allowed.includes(value) ? value : fallback);
  return {
    palette: pick(raw.palette, PROFILE_THEMES.map((t) => t.id), DEFAULT_LOOK.palette),
    font: pick(raw.font, PROFILE_FONTS.map((f) => f.id), DEFAULT_LOOK.font),
    room: pick(raw.room, ROOMS, DEFAULT_LOOK.room),
    wall: pick(raw.wall, ROOM_OPTIONS.wall, 'room'),
    wood: pick(raw.wood, ROOM_OPTIONS.wood, 'room'),
    rug: pick(raw.rug, ROOM_OPTIONS.rug, 'room'),
    lamp: pick(raw.lamp, ROOM_OPTIONS.lamp, 'room'),
    pet: pick(raw.pet, ROOM_OPTIONS.pet, 'none'),
    seasons: raw.seasons === true,
    // The sigil stamped at the foot of every spine: on unless turned off.
    stamp: raw.stamp !== false,
    // The Libby library the member borrows from (its short name in libbyapp.com/library/<name>).
    libby: /^[a-z0-9][a-z0-9-]{1,40}$/.test(String(raw.libby ?? '')) ? raw.libby : '',
  };
}

/** Save a change to someone's look; only known values are kept. */
export function setProfileLook(doc, id, changes) {
  const p = (doc.profiles ?? []).find((x) => x.id === id);
  if (!p) throw new Error('That profile is not here any more.');
  p.look = cleanLook({ ...lookOf(p), ...changes });
  delete p.theme;
  return p;
}

/** Kept for the profile dialog: a palette by its old name. */
export function setProfileTheme(doc, id, themeId) {
  if (!PROFILE_THEMES.some((t) => t.id === themeId)) throw new Error('Unknown theme.');
  return setProfileLook(doc, id, { palette: themeId });
}

/** The season for a date, by the northern-hemisphere calendar. */
export function seasonOf(date = new Date()) {
  const m = date.getMonth() + 1;
  const d = date.getDate();
  const md = m * 100 + d;
  if (md >= 321 && md < 621) return 'spring';
  if (md >= 621 && md < 923) return 'summer';
  if (md >= 923 && md < 1221) return 'autumn';
  return 'winter';
}

/* ------------------------------------------------------------ favourites */

export const MAX_FAVOURITES = 5;

/** Mark a finished book as an all-time favourite, or unmark it. Five at most. */
export function toggleFavourite(library, bookId) {
  const favs = library.favourites ?? [];
  if (favs.includes(bookId)) {
    library.favourites = favs.filter((id) => id !== bookId);
    return library;
  }
  if (favs.length >= MAX_FAVOURITES) throw new Error(`You can keep ${MAX_FAVOURITES} favourites — unmark one first.`);
  if (!(library.books ?? []).some((b) => b.id === bookId)) throw new Error('That book is not on this shelf.');
  library.favourites = [...favs, bookId];
  return library;
}

export const isFavourite = (library, bookId) => (library?.favourites ?? []).includes(bookId);

/** Note that these badges and trophies have been announced, so they are not again. */
export function markAnnounced(library, { badges = [], trophies = [] }) {
  library.badgesSeen = [...new Set([...(library.badgesSeen ?? []), ...badges])];
  library.trophiesSeen = [...new Set([...(library.trophiesSeen ?? []), ...trophies.map(String)])];
  return library;
}
